        _ => {
            logger::debug!("Payment method data is not CardDetail");
        }
    }
    let db = &*state.store;

    let vaulting_result = vault_payment_method(
        state,
        &payment_method_data,
        platform,
        profile,
        None,
        fingerprint_id_from_vault,
        customer_id,
    )
